<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Falling Sand Sandbox</title>
<style>
  :root {
    color-scheme: dark;
    --bg: #101318;
    --panel: #1b2028;
    --panel2: #252c36;
    --text: #edf2f7;
    --muted: #9da8b5;
    --accent: #80cbc4;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background:
      radial-gradient(circle at 50% 0%, #26313d 0, transparent 45%),
      var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  }
  main {
    width: min(94vw, 650px);
    padding: 24px;
    border-radius: 22px;
    background: rgba(27, 32, 40, .94);
    box-shadow: 0 20px 60px rgba(0,0,0,.45), 0 2px 8px rgba(0,0,0,.3);
  }
  h1 {
    margin: 0 0 5px;
    font-size: 1.5rem;
    letter-spacing: .02em;
  }
  p {
    margin: 0 0 18px;
    color: var(--muted);
    font-size: .9rem;
  }
  .stage {
    display: flex;
    justify-content: center;
    padding: 4px;
  }
  canvas {
    display: block;
    width: min(86vw, 520px);
    height: min(86vw, 520px);
    min-width: 400px;
    min-height: 400px;
    max-width: 100%;
    max-height: 70vh;
    border-radius: 12px;
    background: #080a0d;
    box-shadow: inset 0 0 0 1px rgba(255,255,255,.08), 0 8px 22px rgba(0,0,0,.35);
    cursor: crosshair;
    touch-action: none;
  }
  .toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 18px;
    justify-content: center;
  }
  button {
    border: 0;
    border-radius: 999px;
    padding: 11px 16px;
    color: var(--text);
    background: var(--panel2);
    font: inherit;
    font-weight: 650;
    cursor: pointer;
    box-shadow: 0 2px 5px rgba(0,0,0,.28);
    transition: transform .12s, filter .12s, background .12s;
  }
  button:hover { filter: brightness(1.16); }
  button:active { transform: scale(.96); }
  button.active {
    background: var(--accent);
    color: #10201f;
    box-shadow: 0 0 0 3px rgba(128,203,196,.2), 0 3px 8px rgba(0,0,0,.3);
  }
  #clear {
    background: #713e4b;
  }
  .legend {
    margin-top: 13px;
    text-align: center;
    color: var(--muted);
    font-size: .78rem;
  }
</style>
</head>
<body>
<main>
  <h1>Falling Sand</h1>
  <p>Paint matter into the world and watch it settle.</p>
  <div class="stage">
    <canvas id="sand" aria-label="Falling sand simulation"></canvas>
  </div>
  <div class="toolbar" role="toolbar" aria-label="Materials">
    <button id="mat-sand" data-material="sand">Sand</button>
    <button id="mat-water" data-material="water">Water</button>
    <button id="mat-wall" data-material="wall">Wall</button>
    <button id="mat-acid" data-material="acid">Acid</button>
    <button id="mat-empty" data-material="empty">Eraser</button>
    <button id="clear">Clear</button>
  </div>
  <div class="legend">Drag to paint · sand sinks · acid erodes</div>
</main>

<script>
(() => {
  const canvas = document.getElementById("sand");
  const ctx = canvas.getContext("2d");
  const w = 96, h = 96;
  const cells = new Array(w * h).fill("empty");
  let selected = "sand";
  let drawing = false;
  let seed = 0x9e3779b9;

  const colors = {
    empty: "#080a0d",
    sand: "#e6b85c",
    water: "#4d9de0",
    wall: "#727b86",
    acid: "#9be15d"
  };

  function rnd() {
    seed = (seed * 1664525 + 1013904223) >>> 0;
    return seed / 4294967296;
  }
  function idx(x, y) { return y * w + x; }
  function valid(x, y) { return x >= 0 && x < w && y >= 0 && y < h; }
  function get(x, y) { return valid(x, y) ? cells[idx(x, y)] : "wall"; }
  function set(x, y, material) {
    if (valid(x, y) && ["empty","sand","water","wall","acid"].includes(material)) {
      cells[idx(x, y)] = material;
    }
  }
  function clear() { cells.fill("empty"); }

  function swap(x1, y1, x2, y2) {
    const a = idx(x1, y1), b = idx(x2, y2);
    const t = cells[a]; cells[a] = cells[b]; cells[b] = t;
  }

  function liquidEscape(x, y, moved) {
    const dirs = rnd() < .5 ? [-1, 1] : [1, -1];
    for (const dx of dirs) {
      const nx = x + dx;
      if (nx > 0 && nx < w - 1 && get(nx, y) === "empty" && !moved[idx(nx,y)]) {
        cells[idx(nx, y)] = cells[idx(x, y)];
        cells[idx(x, y)] = "empty";
        moved[idx(nx, y)] = true;
        return true;
      }
    }
    return false;
  }

  function dissolveAround(x, y) {
    const spots = [[x, y+1], [x-1,y], [x+1,y]];
    for (const [nx, ny] of spots) {
      if (valid(nx, ny) && (get(nx,ny) === "sand" || get(nx,ny) === "wall")) {
        cells[idx(nx,ny)] = "empty";
      }
    }
  }

  function tick(n = 1) {
    n = Math.max(0, Math.floor(Number(n) || 0));
    for (let step = 0; step < n; step++) {
      const moved = new Uint8Array(w * h);

      for (let y = h - 2; y >= 0; y--) {
        for (let x = 1; x < w - 1; x++) {
          const p = idx(x, y);
          if (moved[p]) continue;
          const type = cells[p];
          if (type === "empty" || type === "wall") continue;

          if (type === "acid") dissolveAround(x, y);

          const below = get(x, y + 1);
          if (below === "empty") {
            swap(x, y, x, y + 1);
            moved[idx(x, y + 1)] = 1;
            continue;
          }

          if (type === "sand" && (below === "water" || below === "acid")) {
            // Let displaced liquid escape locally before the sand sinks.
            if (liquidEscape(x, y + 1, moved)) {
              swap(x, y, x, y + 1);
              moved[idx(x, y + 1)] = 1;
              continue;
            }
            swap(x, y, x, y + 1);
            moved[idx(x, y + 1)] = 1;
            continue;
          }

          const diagonals = rnd() < .5 ? [-1, 1] : [1, -1];
          let didMove = false;
          for (const dx of diagonals) {
            const nx = x + dx, ny = y + 1;
            if (nx > 0 && nx < w - 1 && get(nx, ny) === "empty" && !moved[idx(nx,ny)]) {
              swap(x, y, nx, ny);
              moved[idx(nx,ny)] = 1;
              didMove = true;
              break;
            }
          }
          if (didMove) continue;

          if (type === "water" || type === "acid") {
            const sides = rnd() < .5 ? [-1, 1] : [1, -1];
            for (const dx of sides) {
              const nx = x + dx;
              if (nx > 0 && nx < w - 1 && get(nx, y) === "empty" && !moved[idx(nx,y)]) {
                swap(x, y, nx, y);
                moved[idx(nx,y)] = 1;
                break;
              }
            }
          }
        }
      }
    }
    draw();
  }

  function draw() {
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    const pw = Math.max(1, Math.round(rect.width * dpr));
    const ph = Math.max(1, Math.round(rect.height * dpr));
    if (canvas.width !== pw || canvas.height !== ph) {
      canvas.width = pw; canvas.height = ph;
    }
    ctx.clearRect(0, 0, pw, ph);
    const cw = pw / w, ch = ph / h;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const m = cells[idx(x,y)];
        if (m !== "empty") {
          ctx.fillStyle = colors[m];
          ctx.fillRect(Math.floor(x*cw), Math.floor(y*ch), Math.ceil(cw)+.5, Math.ceil(ch)+.5);
        }
      }
    }
  }

  function paint(e) {
    const r = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - r.left) / r.width * w);
    const y = Math.floor((e.clientY - r.top) / r.height * h);
    for (let dy = -1; dy <= 1; dy++)
      for (let dx = -1; dx <= 1; dx++)
        if (valid(x+dx, y+dy)) set(x+dx, y+dy, selected);
    draw();
  }

  canvas.addEventListener("pointerdown", e => {
    drawing = true; canvas.setPointerCapture(e.pointerId); paint(e);
  });
  canvas.addEventListener("pointermove", e => { if (drawing) paint(e); });
  canvas.addEventListener("pointerup", () => drawing = false);
  canvas.addEventListener("pointercancel", () => drawing = false);

  document.querySelectorAll("[data-material]").forEach(btn => {
    btn.addEventListener("click", () => {
      selected = btn.dataset.material;
      document.querySelectorAll("[data-material]").forEach(b => b.classList.toggle("active", b === btn));
    });
  });
  document.getElementById("clear").addEventListener("click", () => { clear(); draw(); });

  document.getElementById("mat-sand").classList.add("active");
  window.sim = { w, h, tick, get, set, clear };

  let last = 0;
  function animate(t) {
    if (t - last > 45) { tick(1); last = t; }
    requestAnimationFrame(animate);
  }
  draw();
  requestAnimationFrame(animate);
})();
</script>
</body>
</html>
